        cudaEventRecord(a);
        for (int i = 0; i < 50; ++i, ++iters) launchGemm(dA, dB, dC, N);
        cudaEventRecord(b);
        CUDA_CHECK(cudaEventSynchronize(b));
        float ms = 0.0f;
        cudaEventElapsedTime(&ms, a, b);
