#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  Highly-optimised tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Architecture:  BM x BN  block tile  (64 x 64)
 *  Thread map:    16 x 16 = 256 threads per block
 *  Register tile: TM x TN  =  4 x 4  (16 outputs per thread)
 *
 *  Shared-memory As[BM][BN+PAD], Bs[BN+PAD][BN] with PAD=1 to break
 *  bank-conflict aliasing.  Global loads are coalesced because
 *  consecutive threads (tid) advance sCol by 1, which steps through
 *  consecutive columns of the same rows.
 *
 *  Each tile iteration:
 *    – cooperative load  of a 64×64 sub-tile of A and B
 *    – 64-step inner-product with hoisted shared-memory loads
 *    – only one __syncthreads between load and compute, plus an
 *      optional barrier at the end of every iteration except the last.
 */
#define BM  64
#define BN  64
#define TM  4            // register-tile height
#define TN  4            // register-tile width
#define PAD 1            // one-column padding to avoid shared-memory bank conflicts

/*  Shared-memory tile for A:  As[i][j]  ←  A[by*BM + i][t*BN + j]  */
/*  Shared-memory tile for B:  Bs[i][j]  ←  B[t*BN + i][bx*BN + j]  */

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tid = threadIdx.x;      // 0 .. 255

    // Each thread owns a TM×TN sub-tile inside the BM×BN block tile
    const int sRow = tid / 16;        // 0 … 15
    const int sCol = tid % 16;        // 0 … 15

    // output-position of thread's sub-tile corner
    const int outRow = by * BM + sRow * TM;
    const int outCol = bx * BN + sCol * TN;

    const int numTiles = (N + BN - 1) / BN;

    /*  16 accumulators = 4×4 output elements per thread  */
    float acc0  = 0.0f, acc1  = 0.0f, acc2  = 0.0f, acc3  = 0.0f;
    float acc4  = 0.0f, acc5  = 0.0f, acc6  = 0.0f, acc7  = 0.0f;
    float acc8  = 0.0f, acc9  = 0.0f, accA  = 0.0f, accB  = 0.0f;
    float accC  = 0.0f, accD  = 0.0f, accE  = 0.0f, accF  = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ─── cooperative load of As tile ─── */
