            a02 += a0 * Bs[k][ty * TN + 2];
            a03 += a0 * Bs[k][ty * TN + 3];
            a10 += a1 * Bs[k][ty * TN + 0];
            a11 += a1 * Bs[k][ty * TN + 1];
