#include <cuda_runtime.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BM  64
#define BN  64
#define TM  4
#define TN  4
#define PAD 1

__global__ void debugKernel(const float* __restrict__ A,
                            const float* __restrict__ B,
                            float* __restrict__ C,
                            int N,
                            float* result)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int outRow  = by * BM + tx * TM;
    const int outCol  = bx * BN + ty * TN;

    const int numTiles = (N + BN - 1) / BN;

    float a00=0, a01=0, a02=0, a03=0;
    float a10=0, a11=0, a12=0, a13=0;
    float a20=0, a21=0, a22=0, a23=0;
    float a30=0, a31=0, a32=0, a33=0;

    for (int t = 0; t < numTiles; ++t) {
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int ar = by * BM + tx * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int ac = t * BN + ty * TN + c;
                As[tx * TM + r][ty * TN + c] =
                    (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
            }
        }

        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int br = t * BN + tx * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int bc = bx * BN + ty * TN + c;
                Bs[tx * TM + r][ty * TN + c] =
                    (br < N && bc < N) ? B[br * N + bc] : 0.0f;
            }
        }

        __syncthreads();

        // Print first few shared memory values for debugging
        if (tx == 0 && ty == 0 && t == 1) {
            // Write some debug info to result array
            result[0] = As[0][0];
            result[1] = As[0][1];
            result[2] = Bs[0][0];
            result[3] = Bs[0][1];
        }

        #pragma unroll
        for (int k = 0; k < BN; ++k) {
            float a0 = As[tx * TM + 0][k];
            float a1 = As[tx * TM + 1][k];
            float a2 = As[tx * TM + 2][k];
            float a3 = As[tx * TM + 3][k];
            a00 += a0 * Bs[k][ty * TN + 0];
            a01 += a0 * Bs[k][ty * TN + 1];
            a02 += a0 * Bs[k][ty * TN + 2];
            a03 += a0 * Bs[k][ty * TN + 3];
            a10 += a1 * Bs[k][ty * TN + 0];
            a11 += a1 * Bs[k][ty * TN + 1];
            a12 += a1 * Bs[k][ty * TN + 2];
            a13 += a1 * Bs[k][ty * TN + 3];
            a20 += a2 * Bs[k][ty * TN + 0];
            a21 += a2 * Bs[k][ty * TN + 1];
            a22 += a2 * Bs[k][ty * TN + 2];
            a23 += a2 * Bs[k][ty * TN + 3];
            a30 += a3 * Bs[k][ty * TN + 0];
            a31 += a3 * Bs[k][ty * TN + 1];
            a32 += a3 * Bs[k][ty * TN + 2];
            a33 += a3 * Bs[k][ty * TN + 3];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    if (tx == 0 && ty == 0 && t == 1) {
        result[4] = a00;
        result[5] = a01;
        result[6] = a10;
        result[7] = a11;
    }

    if (outRow + 0 < N) {
        C[outRow * N + outCol + 0] = a00;
        C[outRow * N + outCol + 1] = a01;
        C[outRow * N + outCol + 2] = a02;
        C[outRow * N + outCol + 3] = a03;
    }
    if (outRow + 1 < N) {
        C[(outRow + 1) * N + outCol + 0] = a10;
        C[(outRow + 1) * N + outCol + 1] = a11;
        C[(outRow + 1) * N + outCol + 2] = a12;
        C[(outRow + 1) * N + outCol + 3] = a13;
    }
    if (outRow + 2 < N) {
        C[(outRow + 2) * N + outCol + 0] = a20;
        C[(outRow + 2) * N + outCol + 1] = a21;
        C[(outRow + 2) * N + outCol + 2] = a22;
        C[(outRow + 2) * N + outCol + 3] = a23;
    }
    if (outRow + 3 < N) {
        C[(outRow + 3) * N + outCol + 0] = a30;
        C[(outRow + 3) * N + outCol + 1] = a31;
        C[(outRow + 3) * N + outCol + 2] = a32;
        C[(outRow + 3) * N + outCol + 3] = a33;
    }
}

int main() {
    const int N = 8;
    const int TILE = 8;

    // Generate random matrices
    int size = N * N;
    std::vector<float> hA(size), hB(size), hC(size), hR(size);
    for (int i = 0; i < size; ++i) {
        hA[i] = (rand() % 100) / 100.0f;
        hB[i] = (rand() % 100) / 100.0f;
    }

    // CPU reference
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            double acc = 0.0;
            for (int k = 0; k < N; ++k)
                acc += (double)A[i*N+k] * B[k*N+j];
            hR[i*N+j] = (float)acc;
        }

    printf("CPU C[0][0] = %.6f\n", hR[0]);

    // GPU
    float *dA, *dB, *dC, *result;
    cudaMalloc(&dA, size * sizeof(float));
    cudaMalloc(&dB, size * sizeof(float));
    cudaMalloc(&dC, size * sizeof(float));
    cudaMalloc(&result, 8 * sizeof(float));
    cudaMemcpy(dA, hA.data(), size * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(dB, hB.data(), size * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemset(dC, 0, size * sizeof(float));

    dim3 block(TILE, TILE);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    debugKernel<<<grid, block>>>(dA, dB, dC, N, result);
    cudaDeviceSynchronize();

    cudaMemcpy(hC.data(), dC, size * sizeof(float), cudaMemcpyDeviceToHost);
    cudaMemcpy(result, result, 8 * sizeof(float), cudaMemcpyDeviceToHost);

    printf("GPU C[0][0] = %.6f\n", hC[0]);
    printf("GPU As[0][0]=%.6f, As[0][1]=%.6f, Bs[0][0]=%.6f, Bs[0][1]=%.6f\n",
           result[0], result[1], result[2], result[3]);
    printf("GPU a00=%.6f, a01=%.6f, a10=%.6f, a11=%.6f\n",
           result[4], result[5], result[6], result[7]);

    double mse = 0;
    for (int i = 0; i < size; ++i) {
        double d = (double)hC[i] - (double)hR[i];
        mse += d * d;
    }
    printf("MSE = %.6e\n", mse / size);

    cudaFree(dA); cudaFree(dB); cudaFree(dC); cudaFree(result);
    return 0;
}

