/*
 *  Optimised tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: BM x BN = 64 x 64
 *  Thread map: 16 x 16 = 256 threads
 *  Each thread computes 4x4 = 16 output elements using register tiling.
 *  Shared-memory tile is fully populated cooperatively before the inner product.
 *
 *  The key: each thread loads a TM×TN sub-block of the shared-memory tile.
 *  256 threads × 16 elements = 4096 = 64×64 → full tile covered.
 *  After __syncthreads ALL 4096 elements are valid for the inner product.
 *
 *  Global loads are coalesced because consecutive threads advance in the
 *  column direction of the tile (ty*TN + c varies with ty → consecutive cols).
 *
 *  Performance on A40: aiming for 20+ TFLOP/s (≥55% of cuBLAS).
 */
#define BM  64
#define BN  64
#define TM  4
#define TN  4
#define PAD 1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;

    /* Output position: row depends on ty, col on tx (matching TILE=16 pattern). */
    const int outRow  = by * BM + ty * TM;
    const int outCol  = bx * BN + tx * TN;

    const int numTiles = (N + BN - 1) / BN;

    /* 16 accumulators for 4×4 output elements */
    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile (cooperative, 16×16 sub-block per thread) ── */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int ar = by * BM + ty * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int ac = t * BN + tx * TN + c;
                As[ty * TM + r][tx * TN + c] =
                    (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
            }
        }

        /* ── load Bs tile (cooperative) ── */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int br = t * BN + ty * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int bc = bx * BN + tx * TN + c;
                Bs[ty * TM + r][tx * TN + c] =
                    (br < N && bc < N) ? B[br * N + bc] : 0.0f;
            }
        }

        __syncthreads();

        /* ── inner product (hoisted loads, loop unrolled by compiler) ── */
        #pragma unroll
        for (int k = 0; k < BN; ++k) {
            float a0 = As[ty * TM + 0][k];
            float a1 = As[ty * TM + 1][k];
            float a2 = As[ty * TM + 2][k];
            float a3 = As[ty * TM + 3][k];
            a00 += a0 * Bs[k][tx * TN + 0];
            a01 += a0 * Bs[k][tx * TN + 1];
            a02 += a0 * Bs[k][tx * TN + 2];
            a03 += a0 * Bs[k][tx * TN + 3];
            a10 += a1 * Bs[k][tx * TN + 0];
            a11 += a1 * Bs[k][tx * TN + 1];
            a12 += a1 * Bs[k][tx * TN + 2];
            a13 += a1 * Bs[k][tx * TN + 3];
            a20 += a2 * Bs[k][tx * TN + 0];
            a21 += a2 * Bs[k][tx * TN + 1];
            a22 += a2 * Bs[k][tx * TN + 2];
            a23 += a2 * Bs[k][tx * TN + 3];
            a30 += a3 * Bs[k][tx * TN + 0];
            a31 += a3 * Bs[k][tx * TN + 1];
            a32 += a3 * Bs[k][tx * TN + 2];
            a33 += a3 * Bs[k][tx * TN + 3];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    /* ── store 4×4 results ── */
