    printf("Perf: N=%d iters=%lld  total time [s]: %.2f\n", N, iters, elapsed);
    // 2*N^3 FLOPs per GEMM, summed over all launches — the conventional GEMM
    // throughput figure, printed for your own feedback. NOT the graded number
