 *  Thread map:    16 x 16 = 256 threads per block
 *
 *  Shared-memory As[BM][BN+PAD], Bs[BN+PAD][BN].
 *  Cooperative loading: each thread loads one FULL column of the As tile
 *  (TM rows  x  BN cols) and one FULL row of the Bs tile  (BM rows  x  TN cols).
 *  This ensures every element of the shared-memory tile is loaded exactly once,
 *  and every thread reads only the data it loaded.
 *
 *  As loading:  thread (tx,ty) loads TM rows × BN columns  →  BM*BN / 256 = 16 elements per load
 *  Bs loading:  thread (tx,ty) loads BM rows  × TN columns  →  BM*BN / 256 = 16 elements per load
 *
 *  Inner product: each thread computes a TM×TN = 4×4 sub-tile of outputs.
 *  For the inner product, thread (tx,ty) reads As[tx*TM + r][k] and Bs[k][ty*TN + c],
 *  where r=0..3 and c=0..3.  All these values are loaded by the cooperative scheme.
 *
 *  The key insight: thread (tx,ty) reads column k of row tx*TM+r in As,
 *  which was loaded by thread (tx, k/TN) during the As-load phase.
 *  Similarly, Bs is loaded correctly.
 */
#define BM  64
#define BN  64
#define TM  4            // register-tile height
#define TN  4            // register-tile width
#define PAD 1            // padding to avoid shared-memory bank conflicts

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;   // 0 .. 15
    const int ty  = threadIdx.y;   // 0 .. 15

    // output corner for this thread's TM x TN sub-tile
    const int outRow = by * BM + tx * TM;
    const int outCol = bx * BN + ty * TN;

    const int numTiles = (N + BN - 1) / BN;

    // 16 accumulators for TM×TN = 4×4 output elements
    float acc[4][4] = {0};

    for (int t = 0; t < numTiles; ++t) {

        /* ─── load As tile: thread (tx,ty) loads rows tx*TM..tx*TM+3
            across ALL BN columns (ty*TN .. ty*TN+TN-1) ─── */
        // Each thread covers 4 rows and TN columns = 16 elements.
        // The 256 threads together cover all 64 rows × 64 cols = 4096.
        for (int r = 0; r < TM; ++r) {
            const int ar = by * BM + tx * TM + r;
            for (int c = 0; c < TN; ++c) {
                const int ac = t * BN + ty * TN + c;
                As[tx * TM + r][ty * TN + c] =
                    (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
            }
        }

        /* ─── load Bs tile: thread (tx,ty) loads rows tx*TM..tx*TM+3
            across ALL TN columns (ty*TN .. ty*TN+TN-1) ─── */
        for (int r = 0; r < TM; ++r) {
            const int br = t * BN + tx * TM + r;
            for (int c = 0; c < TN; ++c) {
                const int bc = bx * BN + ty * TN + c;
                Bs[tx * TM + r][ty * TN + c] =
                    (br < N && bc < N) ? B[br * N + bc] : 0.0f;
            }
        }

        __syncthreads();

        /* ─── inner product (hoisted As loads, unrolled k-loop) ─── */
        #pragma unroll
        for (int k = 0; k < BN; ++k) {
            float a0 = As[tx * TM + 0][k];
            float a1 = As[tx * TM + 1][k];
            float a2 = As[tx * TM + 2][k];
            float a3 = As[tx * TM + 3][k];
