#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  Optimised tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: BM x BN = 32 x 32
 *  Thread map: 16 x 16 = 256 threads
 *  Register tile: TM x TN = 2 x 2  (4 outputs per thread)
 *
 *  Each thread (tx,ty) loads a 2x2 sub-block of the shared-memory tile
 *  As[tx*2+r][ty*2+c].  256 threads × 4 = 1024 = 32×32 → full tile covered.
 *  After __syncthreads all 1024 elements are valid for the inner product.
 */
#define BM  32
#define BN  32
#define TM  2
#define TN  2
#define PAD 1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;

    const int outRow  = by * BM + tx * TM;
    const int outCol  = bx * BN + ty * TN;

    const int numTiles = (N + BN - 1) / BN;

    /* 4 accumulators per thread */
    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile (cooperative) ── */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int ar = by * BM + tx * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int ac = t * BN + ty * TN + c;
                As[tx * TM + r][ty * TN + c] =
                    (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
            }
        }

        /* ── load Bs tile (cooperative) ── */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int br = t * BN + tx * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int bc = bx * BN + ty * TN + c;
                Bs[tx * TM + r][ty * TN + c] =
                    (br < N && bc < N) ? B[br * N + bc] : 0.0f;
            }
        }

        __syncthreads();

        /* ── inner product with hoisted loads ── */
        #pragma unroll
        for (int k = 0; k < BN; ++k) {
            float a0 = As[tx * TM + 0][k];
            float a1 = As[tx * TM + 1][k];
            acc00 += a0 * Bs[k][ty * TN + 0];
            acc01 += a0 * Bs[k][ty * TN + 1];
            acc10 += a1 * Bs[k][ty * TN + 0];
            acc11 += a1 * Bs[k][ty * TN + 1];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    /* ── store 2x2 results ── */
    if (outRow + 0 < N) {
        C[outRow * N + outCol + 0] = acc00;
        C[outRow * N + outCol + 1] = acc01;
    }
    if (outRow + 1 < N) {
        C[(outRow + 1) * N + outCol + 0] = acc10;
        C[(outRow + 1) * N + outCol + 1] = acc11;
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  Optimised tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: BM x BN = 64 x 64
 *  Thread map: 16 x 16 = 256 threads
 *  Register tile: TM x TN = 4 x 4  (16 outputs per thread)
 *
 *  Cooperative loading: each thread (tx,ty) loads TM rows × 1 column segment.
 *  Specifically, thread (tx,ty) loads rows (tx*4 .. tx*4+TM-1) of the As tile
 *  and columns (ty*4 .. ty*4+TN-1) of the Bs tile.
 *
 *  As loading:  thread loads  TM × 1 columns → TM elements per tile load
 *               But we need ALL BN columns → load in 256*BN / (256*TM) passes?
 *
 *  Actually, the simplest correct approach: each thread loads ALL elements
 *  of its TM rows from global memory (TM × BN elements) and ALL elements
 *  of its TN columns from B (BM × TN elements).  This ensures every
 *  element read during the inner product was loaded by THIS thread,
 *  so no stale-data risk across tile iterations.
 *
 *  Cost:  256 threads × (TM*BN + BM*TN) = 256 × (256+256) = 131 K loads/tile.
 *  Redundant: each shared-mem element loaded 256/(TM) = 64 times for A,
 *  but correctness is guaranteed.
 *
 *  We use a smarter scheme: the shared tile is loaded cooperatively such
 *  that every element is written exactly once by some thread.  Then a
 *  single __syncthreads guarantees all data is valid for the inner product.
 */
#define BM  64
#define BN  64
#define TM  4
#define TN  4
#define PAD 1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;

    const int outRow  = by * BM + tx * TM;
    const int outCol  = bx * BN + ty * TN;

    const int numTiles = (N + BN - 1) / BN;

