#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  Optimised tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: TILE×TILE = 16×16
 *  Thread map: 16×16 = 256 threads (1 output element per thread)
 *  Shared memory: As[TILE][TILE+PAD], Bs[TILE+PAD][TILE] with PAD=1
 *
 *  Optimizations:
 *  - Hoisted shared-memory loads in the inner product loop
 *  - Loop unrolling
 *  - Minimal syncthreads (skipped for last tile)
 *  - Shared memory padding to avoid bank conflicts
 *
 *  Target: push throughput as close to cuBLAS on A40 as possible.
 */
#define TILE 16
#define PAD  1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE + PAD];
    __shared__ float Bs[TILE + PAD][TILE];

    const int row  = blockIdx.y * TILE + threadIdx.y;
    const int col  = blockIdx.x * TILE + threadIdx.x;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile ── */
        As[threadIdx.y][threadIdx.x] =
            (row < N && (t * TILE + threadIdx.x) < N)
                ? A[row * N + t * TILE + threadIdx.x] : 0.0f;

        /* ── load Bs tile ── */
        Bs[threadIdx.y][threadIdx.x] =
            ((t * TILE + threadIdx.y) < N && col < N)
                ? B[(t * TILE + threadIdx.y) * N + col] : 0.0f;

        __syncthreads();

        /* ── inner product (hoisted loads, unrolled) ── */
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a = As[threadIdx.y][k];
            acc += a * Bs[k][threadIdx.x];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

