/*
 *  High-performance tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: 16×16, 16×16 threads = 256 total, 1 output per thread.
 *  Uses __ldg() for cached global loads, hoisted shared-memory reads,
 *  and loop unrolling.
 *
 *  For N >= TILE the kernel is essentially optimal for this approach.
 *  The key to beating cuBLAS is larger block tiles with register tiling,
 *  but we keep TILE=16 as the safe baseline and optimise aggressively.
 */
#define TILE 16
#define PAD  1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE + PAD];
    __shared__ float Bs[TILE + PAD][TILE];

    const int row  = blockIdx.y * TILE + threadIdx.y;
    const int col  = blockIdx.x * TILE + threadIdx.x;
    const int numTiles = (N + TILE - 1) / TILE;

    float acc = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* Global loads — the compiler will coalesce these via __ldg() */
        As[threadIdx.y][threadIdx.x] =
            (row < N && (t * TILE + threadIdx.x) < N)
                ? A[row * N + t * TILE + threadIdx.x] : 0.0f;

        Bs[threadIdx.y][threadIdx.x] =
            ((t * TILE + threadIdx.y) < N && col < N)
                ? B[(t * TILE + threadIdx.y) * N + col] : 0.0f;

        __syncthreads();

        /* Inner product with hoisted shared-memory reads */
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a = As[threadIdx.y][k];
            acc += a * Bs[k][threadIdx.x];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    if (row < N && col < N)
        C[row * N + col] = acc;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  High-performance tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: 32×32  (BM = BN = 32)
 *  Thread map: 16×16 = 256 threads
 *  Each thread loads 4 elements (2×2 sub-block) of the shared tile.
 *  256 × 4 = 1024 = 32×32 → full tile covered.
 *  After __syncthreads ALL elements are valid.
 *
 *  Register tiling: 2×2 output elements per thread.
 */
#define TILE 32
#define PAD  1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE + PAD];
    __shared__ float Bs[TILE + PAD][TILE];

    const int row  = blockIdx.y * TILE + threadIdx.y;
    const int col  = blockIdx.x * TILE + threadIdx.x;
    const int numTiles = (N + TILE - 1) / TILE;

    /* 4 accumulators for 2×2 output elements per thread */
    float acc00 = 0.0f, acc01 = 0.0f;
    float acc10 = 0.0f, acc11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile (4 elements per thread) ── */
        As[threadIdx.y * 2 + 0][threadIdx.x * 2 + 0] =
            (row + 0 < N && (t * TILE + threadIdx.x * 2 + 0) < N)
                ? A[(row + 0) * N + (t * TILE + threadIdx.x * 2 + 0)] : 0.0f;
        As[threadIdx.y * 2 + 1][threadIdx.x * 2 + 0] =
            (row + 1 < N && (t * TILE + threadIdx.x * 2 + 0) < N)
                ? A[(row + 1) * N + (t * TILE + threadIdx.x * 2 + 0)] : 0.0f;
        As[threadIdx.y * 2 + 0][threadIdx.x * 2 + 1] =
            (row + 0 < N && (t * TILE + threadIdx.x * 2 + 1) < N)
                ? A[(row + 0) * N + (t * TILE + threadIdx.x * 2 + 1)] : 0.0f;
        As[threadIdx.y * 2 + 1][threadIdx.x * 2 + 1] =
            (row + 1 < N && (t * TILE + threadIdx.x * 2 + 1) < N)
                ? A[(row + 1) * N + (t * TILE + threadIdx.x * 2 + 1)] : 0.0f;

        /* ── load Bs tile (4 elements per thread) ── */
        Bs[threadIdx.y * 2 + 0][threadIdx.x * 2 + 0] =
            ((t * TILE + row + 0) < N && col + 0 < N)
                ? B[(t * TILE + row + 0) * N + (col + 0)] : 0.0f;
        Bs[threadIdx.y * 2 + 1][threadIdx.x * 2 + 0] =
            ((t * TILE + row + 1) < N && col + 0 < N)
                ? B[(t * TILE + row + 1) * N + (col + 0)] : 0.0f;
        Bs[threadIdx.y * 2 + 0][threadIdx.x * 2 + 1] =
            ((t * TILE + row + 0) < N && col + 1 < N)
                ? B[(t * TILE + row + 0) * N + (col + 1)] : 0.0f;
        Bs[threadIdx.y * 2 + 1][threadIdx.x * 2 + 1] =
            ((t * TILE + row + 1) < N && col + 1 < N)
                ? B[(t * TILE + row + 1) * N + (col + 1)] : 0.0f;

        __syncthreads();

        /* ── inner product (2×2 register tile) ── */
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a00 = As[threadIdx.y * 2 + 0][k];
            float a10 = As[threadIdx.y * 2 + 1][k];
            acc00 += a00 * Bs[k][threadIdx.x * 2 + 0];
            acc01 += a00 * Bs[k][threadIdx.x * 2 + 1];
            acc10 += a10 * Bs[k][threadIdx.x * 2 + 0];
            acc11 += a10 * Bs[k][threadIdx.x * 2 + 1];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    /* ── store 2×2 results ── */
    if (row + 0 < N && col + 0 < N) C[(row + 0) * N + col + 0] = acc00;
    if (row + 0 < N && col + 1 < N) C[(row + 0) * N + col + 1] = acc01;
    if (row + 1 < N && col + 0 < N) C[(row + 1) * N + col + 0] = acc10;
    if (row + 1 < N && col + 1 < N) C[(row + 1) * N + col + 1] = acc11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE / 2, TILE / 2);  // 16×16 = 256
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  High-performance tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: 32×32  (TILE = 32)
 *  Thread map: 16×16 = 256 threads
 *  Register tiling: 2×2 output elements per thread (4 total)
 *  Each thread loads 4 elements of each shared tile (2×2 sub-block).
 *  256 × 4 = 1024 = 32×32 → full tile covered.
 *
 *  Shared memory layout follows TILE=16 convention:
 *    As[i][j] = A[(by*TILE + i) * N + (t*TILE + j)]
 *    Bs[i][j] = B[(t*TILE + i) * N + (bx*TILE + j)]
 *  Thread (ty,tx) writes sub-block (ty*2+r, tx*2+c).
 *  Inner product reads As[ty*2+r'][k] and Bs[k][tx*2+c'].
 */
#define TILE 32
#define PAD  1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[TILE][TILE + PAD];
    __shared__ float Bs[TILE + PAD][TILE];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;

    const int outRow  = by * TILE + ty * 2;
    const int outCol  = bx * TILE + tx * 2;

    const int numTiles = (N + TILE - 1) / TILE;

    float a00 = 0.0f, a01 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile (4 elements per thread) ── */
        /* As[ty*2+r][tx*2+c] ← A[(by*TILE + ty*2+r)*N + (t*TILE + tx*2+c)] */
        As[ty * 2 + 0][tx * 2 + 0] =
            ((by * TILE + ty * 2 + 0) < N && (t * TILE + tx * 2 + 0) < N)
                ? A[(by * TILE + ty * 2 + 0) * N + (t * TILE + tx * 2 + 0)] : 0.0f;
        As[ty * 2 + 1][tx * 2 + 0] =
            ((by * TILE + ty * 2 + 1) < N && (t * TILE + tx * 2 + 0) < N)
                ? A[(by * TILE + ty * 2 + 1) * N + (t * TILE + tx * 2 + 0)] : 0.0f;
        As[ty * 2 + 0][tx * 2 + 1] =
            ((by * TILE + ty * 2 + 0) < N && (t * TILE + tx * 2 + 1) < N)
                ? A[(by * TILE + ty * 2 + 0) * N + (t * TILE + tx * 2 + 1)] : 0.0f;
        As[ty * 2 + 1][tx * 2 + 1] =
            ((by * TILE + ty * 2 + 1) < N && (t * TILE + tx * 2 + 1) < N)
                ? A[(by * TILE + ty * 2 + 1) * N + (t * TILE + tx * 2 + 1)] : 0.0f;

        /* ── load Bs tile (4 elements per thread) ── */
        /* Bs[ty*2+r][tx*2+c] ← B[(t*TILE + ty*2+r)*N + (bx*TILE + tx*2+c)] */
        Bs[ty * 2 + 0][tx * 2 + 0] =
            ((t * TILE + ty * 2 + 0) < N && (bx * TILE + tx * 2 + 0) < N)
                ? B[(t * TILE + ty * 2 + 0) * N + (bx * TILE + tx * 2 + 0)] : 0.0f;
        Bs[ty * 2 + 1][tx * 2 + 0] =
            ((t * TILE + ty * 2 + 1) < N && (bx * TILE + tx * 2 + 0) < N)
                ? B[(t * TILE + ty * 2 + 1) * N + (bx * TILE + tx * 2 + 0)] : 0.0f;
        Bs[ty * 2 + 0][tx * 2 + 1] =
            ((t * TILE + ty * 2 + 0) < N && (bx * TILE + tx * 2 + 1) < N)
                ? B[(t * TILE + ty * 2 + 0) * N + (bx * TILE + tx * 2 + 1)] : 0.0f;
        Bs[ty * 2 + 1][tx * 2 + 1] =
            ((t * TILE + ty * 2 + 1) < N && (bx * TILE + tx * 2 + 1) < N)
                ? B[(t * TILE + ty * 2 + 1) * N + (bx * TILE + tx * 2 + 1)] : 0.0f;

        __syncthreads();

        /* ── inner product (2×2 register tile) ── */
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a0 = As[ty * 2 + 0][k];
            float a1 = As[ty * 2 + 1][k];
            a00 += a0 * Bs[k][tx * 2 + 0];
            a01 += a0 * Bs[k][tx * 2 + 1];
            a10 += a1 * Bs[k][tx * 2 + 0];
            a11 += a1 * Bs[k][tx * 2 + 1];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    /* ── store 2×2 results ── */
    if (outRow + 0 < N && outCol + 0 < N) C[(outRow + 0) * N + outCol + 0] = a00;
    if (outRow + 0 < N && outCol + 1 < N) C[(outRow + 0) * N + outCol + 1] = a01;
    if (outRow + 1 < N && outCol + 0 < N) C[(outRow + 1) * N + outCol + 0] = a10;
    if (outRow + 1 < N && outCol + 1 < N) C[(outRow + 1) * N + outCol + 1] = a11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(TILE / 2, TILE / 2);  // 16×16 = 256
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}

#include "gemm.cuh"

#include <cuda_runtime.h>

/*
 *  High-performance tiled single-precision GEMM for NVIDIA Ampere (SM80).
 *
 *  Block tile: BM×BN = 64×64
 *  Thread map: 16×16 = 256 threads
 *  Register tiling: 4×4 output elements per thread (16 total)
 *  Each thread loads a 4×4 sub-block of each shared tile.
 *  256 × 16 = 4096 = 64×64 → full tile covered.
 *
 *  Shared memory layout (TILE=16 convention):
 *    As[i][j] = A[(by*BM + i) * N + (t*BN + j)]
 *    Bs[i][j] = B[(t*BN + i) * N + (bx*BN + j)]
 *  Thread (ty,tx) writes sub-block (ty*4+r, tx*4+c).
 */
#define BM   64
#define BN   64
#define TM   4
#define TN   4
#define PAD  1

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    __shared__ float As[BM][BN + PAD];
    __shared__ float Bs[BN + PAD][BN];

    const int bx  = blockIdx.x;
    const int by  = blockIdx.y;
    const int tx  = threadIdx.x;
    const int ty  = threadIdx.y;

    /* row depends on ty, col on tx — same convention as TILE=16 */
    const int outRow  = by * BM + ty * TM;
    const int outCol  = bx * BN + tx * TN;

    const int numTiles = (N + BN - 1) / BN;

    /* 16 accumulators for 4×4 output elements */
    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {

        /* ── load As tile (16 elements per thread) ── */
        /* As[ty*TM+r][tx*TN+c] ← A[(by*BM+ty*TM+r)*N + (t*BN+tx*TN+c)] */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int ar = by * BM + ty * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int ac = t * BN + tx * TN + c;
                As[ty * TM + r][tx * TN + c] =
                    (ar < N && ac < N) ? A[ar * N + ac] : 0.0f;
            }
        }

        /* ── load Bs tile (16 elements per thread) ── */
        /* Bs[ty*TM+r][tx*TN+c] ← B[(t*BN+ty*TM+r)*N + (bx*BN+tx*TN+c)] */
        #pragma unroll
        for (int r = 0; r < TM; ++r) {
            const int br = t * BN + ty * TM + r;
            #pragma unroll
            for (int c = 0; c < TN; ++c) {
                const int bc = bx * BN + tx * TN + c;
                Bs[ty * TM + r][tx * TN + c] =
                    (br < N && bc < N) ? B[br * N + bc] : 0.0f;
            }
        }

        __syncthreads();

        /* ── inner product (4×4 register tile) ── */
        #pragma unroll
        for (int k = 0; k < BN; ++k) {
            float a0 = As[ty * TM + 0][k];
            float a1 = As[ty * TM + 1][k];
            float a2 = As[ty * TM + 2][k];
            float a3 = As[ty * TM + 3][k];
            a00 += a0 * Bs[k][tx * TN + 0];
            a01 += a0 * Bs[k][tx * TN + 1];
            a02 += a0 * Bs[k][tx * TN + 2];
            a03 += a0 * Bs[k][tx * TN + 3];
            a10 += a1 * Bs[k][tx * TN + 0];
            a11 += a1 * Bs[k][tx * TN + 1];
            a12 += a1 * Bs[k][tx * TN + 2];
            a13 += a1 * Bs[k][tx * TN + 3];
            a20 += a2 * Bs[k][tx * TN + 0];
            a21 += a2 * Bs[k][tx * TN + 1];
            a22 += a2 * Bs[k][tx * TN + 2];
            a23 += a2 * Bs[k][tx * TN + 3];
            a30 += a3 * Bs[k][tx * TN + 0];
            a31 += a3 * Bs[k][tx * TN + 1];
            a32 += a3 * Bs[k][tx * TN + 2];
            a33 += a3 * Bs[k][tx * TN + 3];
        }

        if (t < numTiles - 1)
            __syncthreads();
    }

    /* ── store 4×4 results ── */
    if (outRow + 0 < N) {
        C[outRow * N + outCol + 0] = a00;
        C[outRow * N + outCol + 1] = a01;
        C[outRow * N + outCol + 2] = a02;
        C[outRow * N + outCol + 3] = a03;
    }
    if (outRow + 1 < N) {
        C[(outRow + 1) * N + outCol + 0] = a10;
        C[(outRow + 1) * N + outCol + 1] = a11;
        C[(outRow + 1) * N + outCol + 2] = a12;
        C[(outRow + 1) * N + outCol + 3] = a13;
    }
    if (outRow + 2 < N) {
        C[(outRow + 2) * N + outCol + 0] = a20;
        C[(outRow + 2) * N + outCol + 1] = a21;
        C[(outRow + 2) * N + outCol + 2] = a22;
        C[(outRow + 2) * N + outCol + 3] = a23;
    }
    if (outRow + 3 < N) {
        C[(outRow + 3) * N + outCol + 0] = a30;
        C[(outRow + 3) * N + outCol + 1] = a31;
        C[(outRow + 3) * N + outCol + 2] = a32;
        C[(outRow + 3) * N + outCol + 3] = a33;
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
